/*--------------------------------------------------------------
 * _rtg_fabric - accumulate every dense crosspoint into its bus.
 *
 * Runs ONCE per block, after the last channel strip and before the
 * first bus node. Clobbers r0-r9, r11-r13, i0-i5, m1, l0-l5.
 *-------------------------------------------------------------*/
.global _rtg_fabric;
_rtg_fabric:
    l0 = 0;
    l1 = 0;
    l2 = 0;
    l3 = 0;
    l4 = 0;
    l5 = 0;

    r0 = dm(_xp_dirty);
    r0 = pass r0;
    if eq jump (pc, .fb_run);
    r0 = 0;
    dm(_xp_dirty) = r0;

    /* ---- rebuild each bus's live strip range ----
     * Forward for the LAST live strip, backward for the FIRST. Two
     * scans rather than a bit mask and a leading-zero count, because
     * this runs only when a ROUTING node has re-prepped and the
     * simple form is the one that is obviously right. */
    r11 = 32;                        /* one bus, in _xpc */
    r12 = _xpc;
    r13 = _xpc + 31;             /* ...and its last strip */
    i4 = _xp_lo;
    i5 = _xp_hi;
    lcntr = 29, do .fb_scan until lce;
        i0 = r12;
        r3 = -1;
        r6 = 0;
        lcntr = 32, do .fb_fwd until lce;
            r7 = dm(i0, 1);
            r7 = pass r7;
            if ne r3 = r6;
        .fb_fwd:
            r6 = r6 + 1;
        i0 = r13;
        r2 = 32;
        r6 = 31;
        lcntr = 32, do .fb_bwd until lce;
            r7 = dm(i0, -1);
            r7 = pass r7;
            if ne r2 = r6;
        .fb_bwd:
            r6 = r6 - 1;
        dm(i4, 1) = r2;
        dm(i5, 1) = r3;
        r12 = r12 + r11;
        r13 = r13 + r11;
    .fb_scan:
        nop;

.fb_run:
    m1 = DSP4_BLOCK_SIZE;             /* one strip, in _rtg_src */
    i3 = _bus_acc_all_ptrs;
    i4 = _xp_lo;
    i5 = _xp_hi;
    r11 = 32;                        /* one bus, in _xpc */
    r12 = _xpc;
    lcntr = 29, do .fb_bus until lce;
        r1 = dm(i3, 1);               /* the bus accumulator      */
        r2 = dm(i4, 1);               /* first live strip         */
        r3 = dm(i5, 1);               /* last live strip          */
        r5 = r3 - r2;
        r5 = r5 + 1;                  /* crosspoints on this bus  */
        r5 = pass r5;
        if le jump (pc, .fb_bnext);
        r6 = r12;
        r6 = r6 + r2;                 /* &_xpc[bus][lo]           */
        r7 = lshift r2 by DSP4_BLOCK_SHIFT;
        r8 = _rtg_src;
        r8 = r8 + r7;                 /* &_rtg_src[lo][0]         */
        i2 = r1;
        lcntr = DSP4_BLOCK_SIZE, do .fb_smp until lce;
            i0 = r8;
            i1 = r6;
            r9 = dm(i2, 1);           /* lo; i2 -> hi             */
            mr0f = r9;
            r9 = dm(i2, 1);           /* hi; i2 -> ex             */
            mr1f = r9;
            r9 = dm(i2, 0);           /* ex                       */
            mr2f = r9;
            /* r0 from R0-R3 and r4 from R4-R7: the multiplier's own
             * operand halves, so this body stays a multifunction
             * candidate if it is ever folded further. */
            lcntr = r5, do .fb_xp until lce;
                r0 = dm(i0, m1);      /* strip's sample          */
                r4 = dm(i1, 1);       /* its coefficient          */
            .fb_xp:
                mrf = mrf + r0 * r4 (ssi);
            r9 = mr2f;
            dm(i2, -1) = r9;          /* ex; i2 -> hi             */
            r9 = mr1f;
            dm(i2, -1) = r9;          /* hi; i2 -> lo             */
            r9 = mr0f;
            dm(i2, 3) = r9;           /* lo; i2 -> next triple    */
            r8 = r8 + 1;              /* next sample, every strip */
        .fb_smp:
            nop;
    .fb_bnext:
        r12 = r12 + r11;
    .fb_bus:
        nop;
    rts;
_rtg_fabric.end:

